const d = $input.first().json;
if (d.errors) throw new Error('Shopify: ' + JSON.stringify(d.errors));
const nodes = d.data.orders.nodes;
const ОПЛАТА = { PAID: 'оплачен', PENDING: 'ждёт оплаты', REFUNDED: 'возврат', PARTIALLY_REFUNDED: 'частичный возврат', AUTHORIZED: 'авторизован', VOIDED: 'отменён' };
const ДОСТАВКА = { FULFILLED: 'отправлен', UNFULFILLED: 'не отправлен', PARTIALLY_FULFILLED: 'отправлен частично', ON_HOLD: 'на удержании' };
const list = nodes.map((o) => ({
  заказ: o.name,
  дата: String(o.createdAt).slice(0, 16).replace('T', ' '),
  сумма: `${o.totalPriceSet.shopMoney.amount} ${o.totalPriceSet.shopMoney.currencyCode}`,
  оплата: ОПЛАТА[o.displayFinancialStatus] || o.displayFinancialStatus,
  доставка: ДОСТАВКА[o.displayFulfillmentStatus] || o.displayFulfillmentStatus,
  страна: (o.shippingAddress && o.shippingAddress.countryCode) || '',
  позиции: o.lineItems.nodes.map((i) => `${i.title} ×${i.quantity}`).join(', '),
}));
return [{ json: { показано: list.length, заказы: list.length ? list : 'заказов пока нет' } }];
